from pathlib import Path
import json,re,html,collections,shutil
b=Path('outputs/taiko-source-analysis')
rows=json.loads((b/'type-index.json').read_text(encoding='utf-8'))
for r in rows:
 p=b/r['source'];stem=p.stem;r['cs']=p.read_text(encoding='utf-8');n=b/'native-typed'/(stem+'.c') if (b/'native-typed'/(stem+'.c')).exists() else b/'native'/(stem+'.c');r['native']=n.read_text(encoding='utf-8') if n.exists() else '';r['nativePath']=n.relative_to(b).as_posix() if n.exists() else '';r['asmPath']='assembly-arm64/'+stem+'.asm' if (b/'assembly-arm64'/(stem+'.asm')).exists() else ''
for name,label in [('native_taiko_entrypoints','Native · điểm vào Taiko (tên suy luận)'),('native_taiko_dependencies','Native · các hàm phụ thuộc')]:
 p=b/'native'/(name+'.c')
 if p.exists():rows.append({'typeIndex':name,'namespace':'Native ARM64','name':label,'assembly':'Native','source':'','cs':'// Không có metadata C# cho nhóm này. Chuyển sang tab mã giả.','native':p.read_text(encoding='utf-8'),'nativePath':'native/'+p.name,'asmPath':'assembly-arm64/'+name+'.asm','methods':0})
for r in rows:
 r['nativeMethods']=' '.join(re.findall(r'/\* RVA ([^\n]+)',r['native']))
 if r['assembly']=='Native':r['methods']=len(re.findall(r'/\* RVA ',r['native']))
summary=(b/'native/summary.txt').read_text() if (b/'native/summary.txt').exists() else 'Đang xử lý'
payload=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
